///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Send_form
 * @description Send form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Send_form = async function () {
    const sbmOptions = {
        id: "tx_Send_form",
        method: "post",
        action: "/amount/amount.do?method=frnIntBatchApplExcelUpload",
        ref: "dma_SendFormReq",
        target: "dlt_bdchrgTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_GetBdchrgInfo
 * @description Get Bdchrg Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetBdchrgInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_GetBdchrgInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_GetBdchrgInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name Send_form
 * @description Send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Send_form = async function () {
    if (!await scwin.dataValidation()) {
        return;
    }
    const telNo = dma_hiddenStore.get("apct_tel_no1") + "-" + dma_hiddenStore.get("apct_tel_no2") + "-" + dma_hiddenStore.get("apct_tel_no3");
    const faxNo = dma_hiddenStore.get("apct_fax_no1") + "-" + dma_hiddenStore.get("apct_fax_no2") + "-" + dma_hiddenStore.get("apct_fax_no3");
    const emailNo = dma_hiddenStore.get("encryp_apct_email1") + '@' + dma_hiddenStore.get("encryp_apct_email2");
    $c.util.getComponent('ipt_encrypApctEmail').setValue(emailNo);
    $c.util.getComponent('ipt_apctTelNo').setValue(telNo);
    $c.util.getComponent('ipt_apctFaxNo').setValue(faxNo);
    if (await $c.win.confirm("신청하시겠습니까?")) {
        scwin.reg_button.setStyle("display", "none");
        const sHost = location.hostname;
        if ($c.util.getComponent('ipt_bndMktactTpCd').getValue() === "309") {
            (document.SendForm || { elements: [] }).action = "/amount/amount.do?method=frnIntBatchApplExcelUpload";
        } else {
            if ($c.util.getComponent('ipt_bndMktactTpCd').getValue() === "303" || $c.util.getComponent('ipt_bndMktactTpCd').getValue() === "304") {
                (document.SendForm || { elements: [] }).action = "/amount/amount.do?method=midRepayBatchApplExcelUpload";
            }
        }
        (document.SendForm || { elements: [] }).target = "_top";
        await scwin.tx_Send_form();
    }
};

/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_batScdaplExcelFilesNm').getValue()) === 0) {
        await $c.win.alert("일괄신청을 위한 엑셀파일을 선택해주십시오.");
        $c.util.getComponent("ipt_batScdaplExcelFilesNm").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name Cancel_form
 * @description Cancel form 처리
 * @returns {void}
 * @hidden N
 */
scwin.Cancel_form = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} mktactDiv mktactDiv
 * @param {*} serverDiv serverDiv
 * @returns {void}
 * @hidden N
 */
scwin.fileDown = function (mktactDiv, serverDiv) {
    if (mktactDiv === '309') {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("https://" + serverDiv + "bonds.krx.co.kr/doc/frn_template.xls"), { id: "hiddenframe", width: "0", height: "0", scrollbars: false, type: "pageFramePopup" }, {});
    } else {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.openPopup((function (__u) { __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("https://" + serverDiv + "bonds.krx.co.kr/doc/repayment_template.xls"), { id: "hiddenframe", width: "0", height: "0", scrollbars: false, type: "pageFramePopup" }, {});
    }
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setCellphoneNo
 * @description set Cellphone No 처리
 * @param {*} pCellphoneNo pCellphoneNo
 * @returns {void}
 * @hidden N
 */
scwin.setCellphoneNo = function (pCellphoneNo) {
    if (pCellphoneNo != null && pCellphoneNo !== '') {
        const pCellphoneNoArr = pCellphoneNo.split('-');
        if (pCellphoneNoArr.length === 3) {
            $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(pCellphoneNoArr[0]);
            $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(pCellphoneNoArr[1]);
            $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(pCellphoneNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setEmail
 * @description set Email 처리
 * @param {*} pEmail pEmail
 * @returns {void}
 * @hidden N
 */
scwin.setEmail = function (pEmail) {
    if (pEmail != null && pEmail !== '') {
        const pEmailArr = pEmail.split('@');
        if (pEmailArr.length === 2) {
            $c.util.getComponent('ipt_encrypApctEmail1').setValue(pEmailArr[0]);
            $c.util.getComponent('ipt_encrypApctEmail2').setValue(pEmailArr[1]);
        } else {

        }
    }
};

/**
 * @method
 * @name setFaxNo
 * @description set Fax No 처리
 * @param {*} pFaxNo pFaxNo
 * @returns {void}
 * @hidden N
 */
scwin.setFaxNo = function (pFaxNo) {
    if (pFaxNo != null && pFaxNo !== '') {
        const pFaxNoArr = pFaxNo.split('-');
        if (pFaxNoArr.length === 3) {
            if (pFaxNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctFaxNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(pFaxNoArr[0]);
            }
            $c.util.getComponent('ipt_apctFaxNo2').setValue(pFaxNoArr[1]);
            $c.util.getComponent('ipt_apctFaxNo3').setValue(pFaxNoArr[2]);
        } else {

        }
    }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(amount#frnintbatchapplexcelupload vs amount#midrepaybatchapplexcelupload) — 어느 것이 «열자마자» 인지 정할 근거가 없다

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getBdchrgInfoDone
 * @description get Bdchrg Info Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getBdchrgInfoDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_chrgId').setValue(result.chrg_id);
    $c.util.getComponent('ipt_apctNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
};

/**
 * @method
 * @name getBdchrgInfo
 * @description get Bdchrg Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getBdchrgInfo = async function () {
    const r = await scwin.tx_fn_GetBdchrgInfo();
    try {
        scwin.getBdchrgInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf90008.fn_GetBdchrgInfo' });
    }
    return r;
};
